select type.*, hotel.name as hotelName
from type
left join hotel on type.hotel_id = hotel.id and hotel.deleted = 0

    type.deleted=0
     and type.id = #{id}
     and type.name like concat('%', #{name}, '%')
     and type.description = #{description}
     and type.price = #{price}
     and type.num = #{num}
     and type.img = #{img}
     and type.hotel_id = #{hotelId}


order by type.id desc

